#!/usr/bin/env python3
"""Derive maps only from executable probe output; no estimated Rust layouts."""
from pathlib import Path
import hashlib,json,re
OUT=Path(__file__).resolve().parent;ROOT=OUT.parents[1]
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def read(name):
    text=(OUT/'logs'/name).read_text();shapes={};offsets={};bounds={};terms=[]
    for line in text.splitlines():
        if m:=re.search(r'layout (.+) (\d+) (\d+)$',line):shapes[m[1]]={'size':int(m[2]),'align':int(m[3])}
        if m:=re.search(r'offset (.+) (\w+) (\d+)$',line):offsets.setdefault(m[1],{})[m[2]]=int(m[3])
        if m:=re.fullmatch(r'bound (\w+) (\d+)',line):bounds[m[1]]=int(m[2])
        if line.startswith('term '):
            p,b,t,n,s=line[5:].split('|');terms.append({'phase':p,'binding':b,'shape':t,'count':int(n),'each_bytes':int(s),'total_bytes':int(n)*int(s)})
    return {'shapes':shapes,'offsets':offsets,'bounds':bounds,'terms':terms,'log_sha256':sha(OUT/'logs'/name)}
def save(name,x):(OUT/name).write_text(json.dumps(x,indent=2)+'\n')
def main():
    prod={p:read('layout-production-'+p+'.log') for p in ['debug','release']}
    unit={p:read('layout-unit-'+p+'.log') for p in ['debug','release']}
    frozen={p:read('layout-frozen-'+p+'.log') for p in ['debug','release']}
    assert frozen['debug']['shapes']==frozen['release']['shapes'];assert frozen['debug']['offsets']==frozen['release']['offsets']
    assert prod['debug']['shapes']==prod['release']['shapes'];assert prod['debug']['offsets']==prod['release']['offsets'];assert prod['debug']['terms']==prod['release']['terms']
    assert unit['debug']['shapes']==unit['release']['shapes'];assert unit['debug']['offsets']==unit['release']['offsets'];assert unit['debug']['terms']==unit['release']['terms']
    receipt=json.loads((OUT/'receipt.json').read_text())
    authority=['docs/swift-executor-stage-contract.md','verification/swift-executor-stage-acceptance.json','verification/swift-executor-stage-contract/acceptance.json','verification/swift-executor-contract-review/foundation-tail-addendum.md','verification/swift-executor-contract-review/observation-chain-map.json','docs/swift-cache-candidate3-acceptance.md','verification/swift-function-cache-root-review/acceptance.json']
    result={'schema':'mixer.swift-executor-eight-layout-maps.v1','target':'aarch64-apple-darwin','revision':receipt['revision'],'toolchain_log':'logs/rustc-version.log','authority_inputs':{p:sha(ROOT/p) for p in authority},'scope':'Actual compiling chosen prerequisite types and declared simultaneous transfer budgets. No interpreter call-chain/constructor/runtime acceptance is inferred.','production':prod,'unit_test_instrumented':unit,'legacy_frozen_layouts':frozen,'debug_release_layouts_equal':True,'root_wiring_integrated':False,'executor_implementation_accepted':False,'final_accounting_accepted':False,'phases':[]}
    groups={
      'state_and_owner':['SwiftExecutionState','SwiftReactorInstance','Lifecycle','Option<SwiftExecutionState>','Option<RuntimeControl>','Option<SwiftFunctionCache>','Option<AccountedWasi>'],
      'arenas':['Value','Control','SwiftFrame','Vec<Value>','Vec<Control>','Vec<SwiftFrame>','Vec<u8>','Vec<Option<u32>>','Option<u32>','[Option<ReservationTicket>; 6]','ReservationTicket','Option<ReservationTicket>'],
      'construction':['ExecutionConstructionPhase<\'static>','PartialState','PartialInstance','ScalarReader<\'static>'],
      'operation':['ExecutionParts<\'static, SwiftMode>','SwiftExecutionOperation<\'static>','ExecutionOperationPhase<\'static>','EntryGuard','SelectedInstruction','FunctionView<\'static>'],
      'growth':['GrowthTransfer','Vec<u8>','Option<ReservationTicket>'],
      'cleanup':['ExecutionCleanupTail','HeaderCompletionParts','SwiftReleaseFailure','CacheCleanupTail<\'static>','CallerDiagnostics','ScalarBorrowInventory'],
      'foundation_tail':['SwiftRunFailure','SwiftRunUsage','ReservationTicket','Option<WasiUsage>','RefundSupplement','FinishSupplement','FlatTickets'],
      'cancellation':['Cancellation'],
    }
    norm=lambda t:re.sub(r'\s+','',t)
    measured={norm(k):k for k in prod['debug']['shapes']}
    for phase,types in groups.items():
        actual=[]
        for t in types:
            assert norm(t) in measured,(phase,t)
            k=measured[norm(t)];actual.append({'type':k,**prod['debug']['shapes'][k],'field_offsets':prod['debug']['offsets'].get(k,{})})
        row={'name':phase,'status':'measured prerequisite; implementation binding pending','chosen_types':actual,'simultaneous_terms':[r for r in prod['debug']['terms'] if r['phase']==phase]}
        if phase in prod['debug']['bounds']:row['additional_named_bytes']=prod['debug']['bounds'][phase]
        if phase=='state_and_owner':row['simultaneous_counts']={'composed_owner':1,'nested_state':1,'nested_cache':1,'nested_wasi':1,'nested_control':1,'exclusive_residual':1,'execution_header_ticket':1};row['exclusive_header_formula']={'state':312,'exclusive_owner_residual':prod['debug']['bounds']['exclusive_owner_residual'],'cleanup_additional':prod['debug']['bounds']['cleanup'],'execution_header_total':prod['debug']['bounds']['execution_header'],'tickets':'one execution header + six distinct arena payload tickets; no second State header'}
        if phase=='arenas':row['simultaneous_counts']={'vector_handles':6,'vector_payload_tickets':6,'swift_frame_elements_maximum':64,'value_elements_maximum':16384,'control_elements_maximum':4096};row['reference_target_capacities']={'values':16384,'controls':4096,'frames':64,'memory_minimum_pages':584,'table_minimum':46713,'globals':5273,'requested_bytes':[262144,131072,4096,38273024,373704,84368],'allocation_witness':'7 tests include exactly6 allocations/66264 bytes for small storage-only witness; not a constructor'}
        if phase=='growth':row['simultaneous_counts']={'old_memory_payload':1,'replacement_memory_payload':1,'old_payload_ticket':1,'replacement_payload_ticket':1,'all_transfer_shapes':'see named terms'};row['767_to_768_payload_overlap_bytes']=100597760
        if phase=='foundation_tail':row['status']='measured shapes; exact final disjoint foundation allowance pending independent root review';row['boundary_map']='final-boundary-map.json'
        if phase=='cancellation':row['simultaneous_counts']={'handles_in_allocator_witness':2,'shared_backing':1,'authoritative_backing_ticket':1};row['observed']={'handles':2,'handle_size':8,'requested_shared_backing_size':24,'requested_shared_backing_align':8,'backing_allocations':1,'clone_allocations':0,'deallocations':1,'ledger_category':'Shared; one existing authoritative backing ticket'}
        result['phases'].append(row)
    save('layout-map.json',result)
    boundary={'schema':'mixer.swift-executor-final-boundary.v1','scope':'Exact chosen final helper and frozen control chain; review input, not an accepted allowance.','source_sha256':{'vm/src/experimental_swift_reactor/execution.rs':sha(ROOT/'vm/src/experimental_swift_reactor/execution.rs'),'vm/src/experimental_swift_reactor/control.rs':sha(ROOT/'vm/src/experimental_swift_reactor/control.rs')},'status':'pending independent root-owned foundation review','before_refund':{'helper':'drop_cleanup_return_storage','ends_by_explicit_scope':['caller returned storage T consumed/dropped','tail.failure consumed/dropped','tail owning wrapper helper frame','HeaderCompletionParts return temporary destructured; full expression ends before if/refund'],'surviving_values':['original RuntimeControl','same execution-header Option<ReservationTicket>','one Option<WasiUsage> final_wasi','outcome output borrow','usage output borrow'],'HeaderCompletionParts':prod['debug']['shapes']['HeaderCompletionParts']},'foundation_classes':{'SwiftRunFailure':{'slots':4,'size':1096,'assignment':'caller outcome; local/new first-failure transfer; forwarded error result/return slots, sequential alternatives; control-owned first failure stays in control header'},'SwiftRunUsage':{'slots':4,'size':504,'assignment':'caller usage; usage local/return; cleanup/final assignment transfer positions, sequential alternatives'},'ReservationTicket':{'slots':6,'size':24,'assignment':'header optional/extraction and owned drop/refund argument transfers; no free payload or reference class implied'},'Option<WasiUsage>':{'slots':6,'size':112,'success_refund':['complete.final_wasi','drop_reserved_with_wasi.wasi','refund_with_wasi.wasi'],'rejected_refund':['complete.final_wasi','drop_reserved_with_wasi.wasi','refund_with_wasi.wasi','cleanup_fault_with_wasi.wasi','fail.wasi','usage.wasi'],'record_cleanup':['complete.final_wasi','record_cleanup.wasi','usage.wasi'],'finish':['complete.final_wasi','finish_owned_cleanup.wasi','usage.wasi']}},'additional_output_reference_lower_bound_bytes':16,'minimal_complete_new_allowance_claimed':False,'independent_review_note':'Starter RefundSupplement and FinishSupplement are incomplete. Independent review must also name match tuple/pattern locals, category receiver/enum/return, get_or_insert receiver/argument/return, record_cleanup pattern/reference, primitive usage/micros u128 and Result transfers, Fault::new return/parameter, and foundation_construction_bytes runtime iterator/try_fold chain.','reason':'Named output refs, control receiver refs, Cursor/Fault, checked arithmetic, clock scalars and whole iterator wrappers have no explicit disjoint final allowance in the frozen foundation. Smaller references are not relabeled as Failure/Usage/Ticket slots.','supplement_shapes':{k:prod['debug']['shapes'][k] for k in ['RefundSupplement','FinishSupplement','Tickets','IntoTickets','FlatTickets']},'supplement_field_offsets':{k:prod['debug']['offsets'][k] for k in ['RefundSupplement','FinishSupplement']},'windows':[{'name':'successful final execution-header refund','observations':3,'additional_named_fields':['outcome borrow','usage borrow','drop self borrow','refund self borrow','refund category/combined/count Option<usize>','successful category/combined/count usize bindings','reservation category/category_mut receiver/parameter/result borrow']},{'name':'rejected final header refund/fault','observations':6,'additional_named_fields':['outcome/usage borrows','five control receiver borrows','cleanup code and invariant parameters','fail Cursor and Fault arguments','usage now Instant','micros duration','underflow category/combined/count Option<usize> retained until refund returns']},{'name':'later record_cleanup','observations':3,'sequential':'previous refund Result temporary ended at the if-body semicolon before record_cleanup','additional_named_fields':['outcome/usage borrows','record_cleanup and usage receiver borrows','record_cleanup mutable failure borrow','usage clock/micros scalars']},{'name':'control consumption','observations':3,'sequential':'record_cleanup call/result ended and outcome assignment completed before finish_owned_cleanup','additional_named_fields':['outcome/usage borrows','finish started/deadline','actual [Option<Ticket>;3]/IntoIter/Flatten wrappers','checked category/combined/count Option<usize>','successful category/combined/count usize bindings','reservation category/category_mut receiver/parameter/result','post-loop now/micros scalars']}],'behavioral_tests':{'success':'actual AccountedWasi ArgsSizesGet observation survives cleanup; no allocation; combined/tickets0 after helper','rejected':'foreign ticket cannot refund original State charge; first release-owner fault; actual WASI observation survives; no allocation; State/combined retain entire header/1ticket','scope':'behavior tests do not close missing disjoint named accounting'}}
    save('final-boundary-map.json',boundary)
    save('regression-scope.json',{'commands':receipt['commands'],'scope':'new layout tests and existing lib/legacy execution suites only; no full target, physical devices or all20 future executor tests','not_run':['full default integration suite matrix beyond legacy executor targets','full 53,777,114-byte target instantiate/initialize/invoke','physical iOS/Android','compiler/signing/store/customer/operational/dogfood/GA qualification']})
    print(json.dumps({'production_shapes':len(prod['debug']['shapes']),'production_offset_types':len(prod['debug']['offsets']),'production_offsets':sum(map(len,prod['debug']['offsets'].values())),'named_terms':len(prod['debug']['terms']),'phases':len(result['phases']),'bounds':prod['debug']['bounds']}))
if __name__=='__main__':main()
